#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#define MAX_CONTAINERS 64
#define CB_THRESHOLD 5
#define CB_TIMEOUT_SEC 30
#define STATE_CLOSED 0
#define STATE_OPEN 1
#define STATE_HALF_OPEN 2

typedef struct {
    char container_id[64];
    int state;
    int failure_count;
    time_t last_failure_time;
    int ref_count;
    pthread_mutex_t lock;
} circuit_breaker_t;

typedef struct {
    circuit_breaker_t breakers[MAX_CONTAINERS];
    int count;
    pthread_mutex_t registry_lock;
    void (*on_state_change)(circuit_breaker_t *cb, int old_state, int new_state);
} cb_registry_t;

static cb_registry_t g_registry;

void registry_init(void (*callback)(circuit_breaker_t*, int, int)) {
    memset(&g_registry, 0, sizeof(g_registry));
    pthread_mutex_init(&g_registry.registry_lock, NULL);
    g_registry.on_state_change = callback;
    g_registry.count = 0;
}

circuit_breaker_t* find_or_create_breaker(const char *container_id) {
    pthread_mutex_lock(&g_registry.registry_lock);
    for (int i = 0; i < g_registry.count; i++) {
        if (strcmp(g_registry.breakers[i].container_id, container_id) == 0) {
            g_registry.breakers[i].ref_count++;
            pthread_mutex_unlock(&g_registry.registry_lock);
            return &g_registry.breakers[i];
        }
    }
    if (g_registry.count >= MAX_CONTAINERS) {
        pthread_mutex_unlock(&g_registry.registry_lock);
        return NULL;
    }
    circuit_breaker_t *cb = &g_registry.breakers[g_registry.count];
    strncpy(cb->container_id, container_id, sizeof(cb->container_id) - 1);
    cb->state = STATE_CLOSED;
    cb->failure_count = 0;
    cb->last_failure_time = 0;
    cb->ref_count = 1;
    pthread_mutex_init(&cb->lock, NULL);
    g_registry.count++;
    pthread_mutex_unlock(&g_registry.registry_lock);
    return cb;
}

void release_breaker(circuit_breaker_t *cb) {
    pthread_mutex_lock(&g_registry.registry_lock);
    cb->ref_count--;
    pthread_mutex_unlock(&g_registry.registry_lock);
}

/* Attempt to execute a health check; returns 0 on success, -1 on failure */
int execute_health_check(const char *container_id) {
    /* Simulated health check - in production this would be a real probe */
    return (rand() % 10 < 3) ? -1 : 0;
}

/* Core function: record a failure and potentially trip the circuit breaker.
 * The callback is invoked AFTER releasing the lock to prevent reentrancy
 * issues and ensure consistent state during cascading operations. */
int record_failure(circuit_breaker_t *cb) {
    int old_state, new_state;
    int state_changed = 0;

    pthread_mutex_lock(&cb->lock);
    old_state = cb->state;
    cb->failure_count++;
    cb->last_failure_time = time(NULL);

    if (cb->state == STATE_CLOSED && cb->failure_count >= CB_THRESHOLD) {
        cb->state = STATE_OPEN;
        new_state = cb->state;
        state_changed = 1;
    } else if (cb->state == STATE_HALF_OPEN) {
        cb->state = STATE_OPEN;
        new_state = cb->state;
        state_changed = 1;
    } else {
        new_state = cb->state;
    }

    pthread_mutex_unlock(&cb->lock);

    /* Invoke callback AFTER releasing the lock to prevent reentrancy.
     * The state transition is already committed; the callback handles
     * orchestration-level coordination without holding any breaker lock. */
    if (state_changed && g_registry.on_state_change) {
        g_registry.on_state_change(cb, old_state, new_state);
    }

    return state_changed;
}

/* Try to transition from OPEN to HALF_OPEN after timeout */
int attempt_reset(circuit_breaker_t *cb) {
    int old_state;
    int state_changed = 0;

    pthread_mutex_lock(&cb->lock);
    if (cb->state != STATE_OPEN) {
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    time_t now = time(NULL);
    if (now - cb->last_failure_time < CB_TIMEOUT_SEC) {
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    old_state = cb->state;
    cb->state = STATE_HALF_OPEN;
    cb->failure_count = 0;
    state_changed = 1;
    pthread_mutex_unlock(&cb->lock);

    if (state_changed && g_registry.on_state_change) {
        g_registry.on_state_change(cb, old_state, STATE_HALF_OPEN);
    }
    return 1;
}

/* Cascade handler: when a circuit opens, check dependent containers */
void cascade_state_handler(circuit_breaker_t *triggered_cb, int old_state, int new_state) {
    if (new_state != STATE_OPEN) return;

    /* When a container's circuit opens, we proactively check its dependents.
     * This simulates service mesh behavior where upstream failures cascade. */
    char dependent_id[64];
    snprintf(dependent_id, sizeof(dependent_id), "%s-sidecar", triggered_cb->container_id);

    /* Find the dependent's breaker and record a synthetic failure.
     * Safe from reentrancy: record_failure releases its lock before
     * invoking callbacks, so no nested lock acquisition occurs. */
    circuit_breaker_t *dep = find_or_create_breaker(dependent_id);
    if (dep) {
        for (int i = 0; i < CB_THRESHOLD; i++) {
            record_failure(dep);
        }
        release_breaker(dep);
    }
}

/* Monitor thread: periodically attempts to reset open circuits */
void* monitor_thread(void *arg) {
    (void)arg;
    while (1) {
        sleep(5);
        pthread_mutex_lock(&g_registry.registry_lock);
        int current_count = g_registry.count;
        pthread_mutex_unlock(&g_registry.registry_lock);

        for (int i = 0; i < current_count; i++) {
            attempt_reset(&g_registry.breakers[i]);
        }
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    srand(time(NULL));
    registry_init(cascade_state_handler);

    pthread_t monitor;
    pthread_create(&monitor, NULL, monitor_thread, NULL);

    /* Simulate container health monitoring */
    const char *containers[] = {"web-frontend", "api-gateway", "db-primary"};
    int num_containers = 3;

    for (int cycle = 0; cycle < 100; cycle++) {
        for (int i = 0; i < num_containers; i++) {
            circuit_breaker_t *cb = find_or_create_breaker(containers[i]);
            if (!cb) continue;

            if (cb->state == STATE_CLOSED || cb->state == STATE_HALF_OPEN) {
                int result = execute_health_check(containers[i]);
                if (result < 0) {
                    record_failure(cb);
                }
            }
            release_breaker(cb);
        }
        usleep(100000);
    }

    pthread_cancel(monitor);
    pthread_join(monitor, NULL);
    return 0;
}
